layer_gelu.reference:
class GELU(Module):
    def forward(self, x):
        self._x = x.copy()
        self._t = np.tanh(np.sqrt(2 / np.pi) * (x + .044715 * x**3))
        return .5 * x * (1 + self._t)

    def backward(self, g):
        x, t = self._x, self._t
        du = np.sqrt(2 / np.pi) * (1 + 3 * .044715 * x**2)
        return g * (.5 * (1 + t) + .5 * x * (1 - t**2) * du)

