def solve(S):
    mask=np.triu(np.ones(S.shape[-2:],dtype=bool),1)
    z=np.where(mask,-np.inf,S)
    z=z-z.max(axis=-1,keepdims=True)
    e=np.exp(z)
    return e/e.sum(axis=-1,keepdims=True)

