class Linear(Module):

    def __init__(self, C, D, use_bias=True, *, rng=None, init_std=None, init_scale=1.0):
        if init_std is None:
            values = initialize((C, D), rng)
        else:
            if rng is None:
                rng = np.random.default_rng(0)
            values = rng.normal(0, init_std, (C, D))
        self.W = Parameter(values * init_scale)
        self.b = Parameter(np.zeros(D)) if use_bias else None

    def forward(self, x):
        self._shape = x.shape
        self._x2 = x.reshape(-1, self.W.data.shape[0]).copy()
        y2 = self._x2 @ self.W.data
        if self.b is not None:
            y2 = y2 + self.b.data
        return y2.reshape(*x.shape[:-1], self.W.data.shape[1])

    def backward(self, g):
        g2 = g.reshape(-1, self.W.data.shape[1])
        self.W.grad += self._x2.T @ g2
        if self.b is not None:
            self.b.grad += g2.sum(axis=0)
        return (g2 @ self.W.data.T).reshape(self._shape)

class Embedding(Module):

    def __init__(self, V, C, *, rng=None, init_std=0.02):
        if rng is None:
            rng = np.random.default_rng(0)
        self.weight = Parameter(rng.normal(0, init_std, (V, C)))

    def forward(self, ids):
        self._ids = np.asarray(ids).copy()
        return self.weight.data[self._ids]

    def backward(self, g):
        np.add.at(self.weight.grad, self._ids.reshape(-1), g.reshape(-1, g.shape[-1]))
        return None

class MLP(Module):

    def __init__(self, C, hidden, *, rng=None, init_std=None, init_scale=1.0):
        self.fc1 = Linear(C, hidden, rng=rng, init_std=init_std)
        self.act = GELU()
        self.fc2 = Linear(hidden, C, rng=rng, init_std=init_std, init_scale=init_scale)

    def forward(self, x):
        return self.fc2(self.act(self.fc1(x)))

    def backward(self, g):
        return self.fc1.backward(self.act.backward(self.fc2.backward(g)))

class MLPBranch(Module):

    def __init__(self, C, hidden, eps=1e-05, *, rng=None, init_std=None, init_scale=1.0):
        self.norm = RMSNorm(C, eps)
        self.mlp = MLP(C, hidden, rng=rng, init_std=init_std, init_scale=init_scale)

    def forward(self, x):
        return self.mlp(self.norm(x))

    def backward(self, g):
        return self.norm.backward(self.mlp.backward(g))

class MultiHeadAttention(Module):

    def __init__(self, C, H, *, rng=None, init_std=None, init_scale=1.0):
        if C % H:
            raise ValueError('C 必须能被 H 整除')
        self.C, self.H = (C, H)
        self.qkv = Linear(C, 3 * C, rng=rng, init_std=init_std)
        self.core = AttentionCore(True)
        self.proj = Linear(C, C, rng=rng, init_std=init_std, init_scale=init_scale)

    def forward(self, x):
        B, T, C = x.shape
        self._shape = x.shape
        q, k, v = np.split(self.qkv(x), 3, axis=-1)
        split = lambda a: a.reshape(B, T, self.H, C // self.H).transpose(0, 2, 1, 3)
        y = self.core(split(q), split(k), split(v))
        return self.proj(y.transpose(0, 2, 1, 3).reshape(B, T, C))

    def backward(self, g):
        B, T, C = self._shape
        dy = self.proj.backward(g).reshape(B, T, self.H, C // self.H).transpose(0, 2, 1, 3)
        grads = self.core.backward(dy)
        joined = [a.transpose(0, 2, 1, 3).reshape(B, T, C) for a in grads]
        return self.qkv.backward(np.concatenate(joined, axis=-1))

class Block(Module):

    def __init__(self, C, H, hidden, *, rng=None, init_std=None, init_scale=1.0):
        self.norm1 = RMSNorm(C)
        self.attn = MultiHeadAttention(C, H, rng=rng, init_std=init_std, init_scale=init_scale)
        self.ffn = MLPBranch(C, hidden, rng=rng, init_std=init_std, init_scale=init_scale)

    def forward(self, x):
        x1 = x + self.attn(self.norm1(x))
        return x1 + self.ffn(x1)

    def backward(self, g):
        g1 = g + self.ffn.backward(g)
        return g1 + self.norm1.backward(self.attn.backward(g1))
